(()=>{const cfg=window.NIHONGO_ADS;if(!cfg||!/^ca-pub-\d{16}$/.test(cfg.client))return;const box=document.getElementById('adPlacement');const label={bn:'বিজ্ঞাপন',en:'Advertisement'};window.updateAdLabel=lang=>{box.querySelector('small').textContent=label[lang]||label.en};if(/^\d+$/.test(cfg.slot)){const ad=document.createElement('ins');ad.className='adsbygoogle';ad.style.display='block';ad.dataset.adClient=cfg.client;ad.dataset.adSlot=cfg.slot;ad.dataset.adFormat='auto';ad.dataset.fullWidthResponsive='true';box.append(ad);(window.adsbygoogle=window.adsbygoogle||[]).push({})}else{box.classList.add('auto-placement')}if(cfg.autoAds){const script=document.createElement('script');script.async=true;script.crossOrigin='anonymous';script.src='https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client='+cfg.client;document.head.append(script)}})();
